/* ========================================
   Volta Studio — Global Styles
   ======================================== */

/* CSS Variables */
:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --accent-terracotta: #C67B5C;
  --accent-sage: #8A9B7A;
  --accent-sand: #D4C4A8;
  --border: rgba(26, 26, 26, 0.12);
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ========================================
   Typography
   ======================================== */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

/* ========================================
   Header & Navigation
   ======================================== */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 3rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.desktop-nav {
  display: flex;
  gap: 2.5rem;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  position: relative;
  padding-bottom: 2px;
  transition: opacity 0.2s ease;
}

.desktop-nav a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.desktop-nav a:hover::after {
  width: 100%;
}

.desktop-nav a:hover {
  opacity: 0.7;
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 110;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  margin: 5px 0;
  transition: all 0.3s ease;
}

.menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 105;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  transition: opacity 0.2s ease;
}

.mobile-overlay a:hover {
  opacity: 0.5;
}

/* ========================================
   Main Content Spacing
   ======================================== */

main {
  padding-top: 80px;
}

/* ========================================
   Hero Section
   ======================================== */

.hero {
  padding: 6rem 3rem 4rem;
  max-width: 1400px;
  margin: 0 auto;
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  max-width: 900px;
}

/* ========================================
   Media Showcase
   ======================================== */

.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1.2fr 1fr;
  gap: 1.5rem;
  padding: 2rem 3rem 5rem;
  max-width: 1400px;
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

.media-block.terracotta {
  background: var(--accent-terracotta);
}

.media-block.sage {
  background: var(--accent-sage);
}

.media-block.sand {
  background: var(--accent-sand);
}

/* ========================================
   Client Marquee
   ======================================== */

.marquee-section {
  padding: 4rem 0;
  overflow: hidden;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  will-change: transform;
  padding: 1rem 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: 3rem;
  padding-right: 3rem;
  flex-shrink: 0;
}

.marquee-track span {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text);
  flex-shrink: 0;
}

.marquee-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-muted);
  flex-shrink: 0;
}

/* Animations */
@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row.row-1 .marquee-track {
  animation: marquee-left 30s linear infinite;
}

.marquee-row.row-2 .marquee-track {
  animation: marquee-right 35s linear infinite;
}

.marquee-row.row-3 .marquee-track {
  animation: marquee-left 40s linear infinite;
}

/* ========================================
   About Section
   ======================================== */

.about-section {
  padding: 6rem 3rem;
  max-width: 1400px;
  margin: 0 auto;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.about-text {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  line-height: 1.7;
  max-width: 800px;
  color: var(--text);
}

.about-text p + p {
  margin-top: 1.5rem;
}

/* ========================================
   Founder Letter Page
   ======================================== */

.founder-letter {
  padding: 4rem 3rem 8rem;
  max-width: 720px;
  margin: 0 auto;
}

.letter-greeting {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  margin-bottom: 2.5rem;
  line-height: 1.3;
}

.letter-body {
  font-size: 1.125rem;
  line-height: 1.85;
  color: var(--text);
}

.letter-body p + p {
  margin-top: 1.75rem;
}

.letter-signoff {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-top: 3rem;
}

/* ========================================
   Services Page
   ======================================== */

.services-page {
  padding: 4rem 3rem 8rem;
  max-width: 1000px;
  margin: 0 auto;
}

.philosophy-section {
  margin-bottom: 5rem;
}

.philosophy-heading {
  font-size: clamp(2rem, 5vw, 4rem);
  margin-bottom: 2rem;
}

.philosophy-body {
  font-size: 1.125rem;
  line-height: 1.8;
  max-width: 700px;
}

.philosophy-body p + p {
  margin-top: 1.5rem;
}

.section-divider {
  height: 1px;
  background: var(--border);
  margin: 4rem 0;
}

.services-heading {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: 3rem;
}

.service-item {
  margin-bottom: 3rem;
}

.service-item h3 {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 0.75rem;
}

.service-item p {
  font-size: 1.0625rem;
  line-height: 1.75;
  color: var(--text);
  max-width: 700px;
}

/* ========================================
   Clients Page
   ======================================== */

.clients-page {
  padding: 4rem 3rem 8rem;
  max-width: 1200px;
  margin: 0 auto;
}

.clients-heading {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: 4rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2.5rem;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--text-muted);
}

/* ========================================
   Contact Page
   ======================================== */

.contact-page {
  min-height: calc(100vh - 80px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem 3rem;
  text-align: center;
}

.contact-title {
  font-size: clamp(4rem, 15vw, 14rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  gap: 2.5rem;
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 600;
  position: relative;
  padding-bottom: 3px;
  transition: opacity 0.2s ease;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.contact-links a:hover::after {
  width: 100%;
}

.contact-links a:hover {
  opacity: 0.6;
}

/* ========================================
   Responsive
   ======================================== */

@media (max-width: 900px) {
  .desktop-nav {
    display: none;
  }

  .menu-toggle {
    display: block;
  }

  .site-header {
    padding: 1.25rem 1.5rem;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    padding: 2rem 1.5rem 4rem;
  }

  .media-block {
    aspect-ratio: 16 / 9;
  }

  .hero {
    padding: 4rem 1.5rem 3rem;
  }

  .about-section {
    padding: 4rem 1.5rem;
  }

  .founder-letter,
  .services-page,
  .clients-page {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 2.5rem 2rem;
  }

  .contact-page {
    padding: 4rem 1.5rem;
  }
}

@media (max-width: 600px) {
  .clients-grid {
    grid-template-columns: 1fr;
  }

  .contact-links {
    flex-direction: column;
    gap: 1.25rem;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation: none !important;
  }
}

/* ========================================
   Volta Studio — Global Scripts
   ======================================== */

document.addEventListener('DOMContentLoaded', () => {
  initMobileMenu();
  initMarquee();
});

/* Mobile Menu Toggle */
function initMobileMenu() {
  const toggle = document.querySelector('.menu-toggle');
  const overlay = document.querySelector('.mobile-overlay');
  if (!toggle || !overlay) return;

  toggle.addEventListener('click', () => {
    toggle.classList.toggle('active');
    overlay.classList.toggle('active');
    document.body.style.overflow = overlay.classList.contains('active') ? 'hidden' : '';
  });

  overlay.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => {
      toggle.classList.remove('active');
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    });
  });
}

/* Marquee — duplicate track content for seamless loop */
function initMarquee() {
  document.querySelectorAll('.marquee-row').forEach(row => {
    const track = row.querySelector('.marquee-track');
    if (!track) return;
    // Clone the track content once to create seamless loop
    track.innerHTML += track.innerHTML;
  });
}
